add_action( 'woocommerce_after_cart_item_name', 'perfectpixel_stock_in_cart', 10, 2 );

function perfectpixel_stock_in_cart( $cart_item, $cart_item_key ) {
	$product = $cart_item['data'] ?? null;
	if ( $product && $product->managing_stock() ) {
		echo wc_get_stock_html( $product ); // phpcs:ignore WordPress.Security.EscapeOutput
	}
}
